// The Teimeris adapter, as an npm package: the descriptor a consumer
// hands the SDK, and the typed façade over the engine's own operations.
//
// HAND-WRITTEN. `engine.js` and `engine.d.ts` beside it are generated by
// `cargo xtask engine` from the engine's own description; what is here is
// the one thing a package has to decide, which is where its platform
// binary is and what its configuration means.
//
// **This package is AGPL-3.0**, because Teimeris is. The SDK is
// Apache-2.0 and never links it: it loads this adapter at run time, so
// the licence stays on this side of the boundary (ADR-0029).

import { createRequire } from 'node:module';
import { existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export { teimeris as engine, TeimerisEngine } from './engine.js';

const require = createRequire(import.meta.url);
const HERE = dirname(fileURLToPath(import.meta.url));

/**
 * The npm package that carries this host's prebuilt adapter, as
 * `@teistro/ephemeris-teimeris-<platform>-<arch>` in Node's own words
 * for the host.
 *
 * A release publishes one such package per platform and this one depends
 * on all of them optionally, so npm installs the matching one — the same
 * shape the SDK's own addon uses, for the same reason.
 */
export function platformPackage() {
  return `@teistro/ephemeris-teimeris-${process.platform}-${process.arch}`;
}

/** What the adapter's library is called on this platform. */
function libraryName() {
  if (process.platform === 'win32') return 'teistro_ephemeris_teimeris.dll';
  if (process.platform === 'darwin') return 'libteistro_ephemeris_teimeris.dylib';
  return 'libteistro_ephemeris_teimeris.so';
}

/** The library inside its platform package, or null when npm installed none. */
function packaged() {
  try {
    return require.resolve(`${platformPackage()}/${libraryName()}`);
  } catch {
    return null;
  }
}

/**
 * The adapter's platform binary: the one a path names, then the one npm
 * installed for this host, then this repository's own build.
 *
 * A consumer only ever has the second; a contributor only ever has the
 * third, because the platform packages are published rather than checked
 * in.
 *
 * @param {string} [named] a path, when a caller has one
 * @returns {string} the path, or a refusal naming every place it looked
 */
export function binary(named) {
  const candidates = [
    named,
    process.env.TEISTRO_TEIMERIS_ADAPTER,
    packaged(),
    join(HERE, '..', 'rust', 'target', 'release', libraryName()),
    join(HERE, '..', 'rust', 'target', 'debug', libraryName()),
  ].filter(Boolean);
  const found = candidates.find((path) => existsSync(path));
  if (!found) {
    throw new Error(
      `no Teimeris adapter for ${process.platform}-${process.arch}. Looked in:\n  ${candidates.join(
        '\n  ',
      )}\nInstall the prebuilt adapter with \`npm install ${platformPackage()}\` (npm normally does that for you), build it with \`cargo build --release\` in \`adapters/ephemeris-teimeris/rust\`, or set TEISTRO_TEIMERIS_ADAPTER to its path.`,
    );
  }
  return found;
}

/**
 * The descriptor: what an `ephemeris` chain takes (ADR-0029).
 *
 * ```js
 * import teimeris from '@teistro/ephemeris-teimeris';
 *
 * const sdk = new Context({ ephemeris: [teimeris({ dataDir: './ephe' })] });
 * ```
 *
 * **It fails here** — at the call, in the line that names the engine —
 * when the adapter is not installed, rather than when a chart is cast.
 * That is the whole reason a descriptor is a value rather than a string
 * the SDK looks up.
 *
 * @param {object} [options]
 * @param {string} [options.dataDir] where the engine's data files are;
 *   it looks beside its own build when this is omitted
 * @param {string} [options.profile] the engine's own accuracy profile
 * @param {string} [options.binary] the platform binary, when a caller
 *   would rather name it than let this package find it
 */
export default function teimeris(options = {}) {
  const { dataDir, profile, binary: named } = options;
  // The keys are the **adapter's**, and its own `Config` spells them in
  // camelCase with `deny_unknown_fields` — so a misspelling is refused
  // rather than silently defaulted. `cargo xtask check-package` caught
  // `data_dir` here, which nothing else could: the SDK passes this
  // object through as JSON and reads none of it.
  const config = {};
  if (dataDir !== undefined) config.dataDir = dataDir;
  if (profile !== undefined) config.profile = profile;
  return Object.freeze({ plugin: binary(named), config: Object.freeze(config) });
}
